import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Guia do Projeto","description":"","frontmatter":{"status":"ativo","tipo":"indice-projeto","atualizado_em":"2026-08-03T00:00:00.000Z"},"headers":[],"relativePath":"projeto/index.md","filePath":"projeto/index.md","lastUpdated":null}'),d={name:"projeto/index.md"};function s(n,e,i,l,c,p){return t(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="guia-do-projeto" tabindex="-1">Guia do Projeto <a class="header-anchor" href="#guia-do-projeto" aria-label="Permalink to &quot;Guia do Projeto&quot;">​</a></h1><p>Esta documentação explica o Akiba pela estrutura real do código. A ideia é simples: quando você abrir uma pasta, esta doc deve explicar o que existe ali, para que serve e como criar algo novo seguindo o padrão do projeto.</p><h2 id="por-onde-comecar" tabindex="-1">Por Onde Começar <a class="header-anchor" href="#por-onde-comecar" aria-label="Permalink to &quot;Por Onde Começar&quot;">​</a></h2><ol><li>Leia <a href="./estrutura-geral">Estrutura Geral</a> para entender o mapa do projeto.</li><li>Leia <a href="./fluxos/feature">Fluxo de uma Feature</a> para entender como uma mudança passa por rota, controller, action, model e interface.</li><li>Use as páginas por tipo de arquivo quando estiver mexendo em uma camada específica.</li></ol><h2 id="consulta-rapida" tabindex="-1">Consulta Rápida <a class="header-anchor" href="#consulta-rapida" aria-label="Permalink to &quot;Consulta Rápida&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Se você vai mexer em...</th><th>Leia</th></tr></thead><tbody><tr><td>Rota nova ou endpoint</td><td><a href="./backend/rotas">Rotas</a></td></tr><tr><td>Configuração ou variável ENV</td><td><a href="./configuracoes">Configurações e ENV</a></td></tr><tr><td>Login do painel</td><td><a href="./autenticacao-interna">Painel Administrativo</a></td></tr><tr><td>OAuth público</td><td><a href="./oauth">OAuth para Site Publico</a></td></tr><tr><td>Tela Inertia</td><td><a href="./backend/controllers">Controllers</a> e <a href="./frontend/interface">Interface</a></td></tr><tr><td>Page Svelte</td><td><a href="./frontend/pages">Pages</a></td></tr><tr><td>Layout público ou privado</td><td><a href="./frontend/layouts">Layouts</a></td></tr><tr><td>Formulário</td><td><a href="./backend/requests">Requests</a>, <a href="./backend/actions">Actions</a> e <a href="./frontend/componentes">Componentes</a></td></tr><tr><td>Formulário Svelte</td><td><a href="./frontend/forms">Forms</a></td></tr><tr><td>Componente ou widget</td><td><a href="./frontend/componentes">Componentes e Widgets</a></td></tr><tr><td>Estado compartilhado</td><td><a href="./frontend/stores">Stores</a></td></tr><tr><td>Helper frontend</td><td><a href="./frontend/utils">Utils</a></td></tr><tr><td>Lista fixa de opções</td><td><a href="./frontend/constants">Constants</a></td></tr><tr><td>Regra de salvar/alterar</td><td><a href="./backend/actions">Actions</a></td></tr><tr><td>Listagem com busca</td><td><a href="./backend/filters">Filters</a> e <a href="./backend/resources">Resources</a></td></tr><tr><td>Dados enviados para Svelte</td><td><a href="./backend/resources">Resources</a></td></tr><tr><td>Permissões</td><td><a href="./backend/policies">Policies</a></td></tr><tr><td>Middleware ou prop global Inertia</td><td><a href="./backend/middlewares">Middlewares</a></td></tr><tr><td>Integração externa</td><td><a href="./backend/services">Services</a></td></tr><tr><td>Command ou schedule</td><td><a href="./backend/commands">Commands e Schedules</a></td></tr><tr><td>Tabela ou coluna nova</td><td><a href="./database/banco">Banco de Dados</a> e <a href="./backend/models">Models</a></td></tr><tr><td>Factory</td><td><a href="./database/factories">Factories</a></td></tr><tr><td>Seeder ou permissão inicial</td><td><a href="./database/seeders">Seeders</a></td></tr><tr><td>Teste</td><td><a href="./testes">Testes</a></td></tr></tbody></table><h2 id="areas-principais" tabindex="-1">Áreas Principais <a class="header-anchor" href="#areas-principais" aria-label="Permalink to &quot;Áreas Principais&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Área</th><th>Pasta</th><th>O que você encontra</th></tr></thead><tbody><tr><td>Backend</td><td><code>app/</code></td><td>Controllers, actions, models, filters, requests, resources, policies e services.</td></tr><tr><td>Rotas</td><td><code>routes/</code></td><td>Entrada HTTP da aplicação, separada por contexto.</td></tr><tr><td>Interface</td><td><code>resources/js/</code></td><td>Páginas Svelte, layouts, componentes, widgets, stores e utilitários.</td></tr><tr><td>Banco</td><td><code>database/</code></td><td>Migrations, seeders e factories.</td></tr><tr><td>Testes</td><td><code>tests/</code></td><td>Testes unitários, feature, comandos, services, actions e models.</td></tr><tr><td>Docs</td><td><code>docs/</code></td><td>Documentação VitePress do projeto.</td></tr></tbody></table><h2 id="regra-mental" tabindex="-1">Regra Mental <a class="header-anchor" href="#regra-mental" aria-label="Permalink to &quot;Regra Mental&quot;">​</a></h2><p>Uma feature normalmente passa por este caminho:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Rota</span></span>
<span class="line"><span>  -&gt; Controller</span></span>
<span class="line"><span>     -&gt; Request</span></span>
<span class="line"><span>     -&gt; Policy</span></span>
<span class="line"><span>     -&gt; Action</span></span>
<span class="line"><span>        -&gt; Model</span></span>
<span class="line"><span>     -&gt; Resource</span></span>
<span class="line"><span>  -&gt; Página Svelte</span></span>
<span class="line"><span>     -&gt; Componentes/widgets</span></span></code></pre></div><p>Nem toda feature usa todas as camadas. Uma tela apenas de leitura pode usar rota, controller, filter, resource e página. Uma ação de salvar normalmente usa request, policy e action.</p><h2 id="convencoes-gerais" tabindex="-1">Convenções Gerais <a class="header-anchor" href="#convencoes-gerais" aria-label="Permalink to &quot;Convenções Gerais&quot;">​</a></h2><ul><li>Controllers coordenam.</li><li>Requests validam.</li><li>Policies autorizam.</li><li>Actions executam regra de negócio.</li><li>Models representam dados e relações.</li><li>Filters montam queries reutilizáveis.</li><li>Resources formatam dados para a interface.</li><li>Pages Svelte organizam a tela.</li><li>Components são peças pequenas.</li><li>Widgets são blocos maiores de domínio.</li></ul>`,14)])])}const h=a(d,[["render",s]]);export{m as __pageData,h as default};
